from dj_rest_auth.views import PasswordChangeView, PasswordResetConfirmView, PasswordResetView
from django.urls import path
from authentication.views.auth import LoginView, SessionRefreshView, healthz, jwks
from authentication.views.devices import DeviceListView, DeviceRevokeView, LogoutAllView, SessionLogoutView
from authentication.views.internal import SessionStatusView
from authentication.views.registration import ActivationResendView, ActivationView, StudentRegisterView
urlpatterns = [path('healthz', healthz, name='healthz'), path('api/v1/auth/.well-known/jwks.json', jwks, name='identity-jwks'), path('api/v1/auth/login', LoginView.as_view(), name='identity-login'), path('api/v1/internal/auth/session-status', SessionStatusView.as_view(), name='identity-session-status'), path('api/v1/auth/register', StudentRegisterView.as_view(authentication_classes=[]), name='identity-register'), path('api/v1/auth/activate', ActivationView.as_view(authentication_classes=[]), name='identity-activate'), path('api/v1/auth/activation/resend', ActivationResendView.as_view(authentication_classes=[]), name='identity-resend'), path('api/v1/auth/refresh', SessionRefreshView.as_view(), name='identity-refresh'), path('api/v1/auth/logout', SessionLogoutView.as_view(), name='identity-logout'), path('api/v1/auth/logout-all', LogoutAllView.as_view(), name='identity-logout-all'), path('api/v1/auth/sessions', DeviceListView.as_view(), name='identity-sessions'), path('api/v1/auth/sessions/<uuid:session_id>', DeviceRevokeView.as_view(), name='identity-revoke'), path('api/v1/auth/password-reset/request', PasswordResetView.as_view(throttle_scope='recovery', authentication_classes=[]), name='identity-password-reset'), path('api/v1/auth/password-reset/confirm', PasswordResetConfirmView.as_view(throttle_scope='recovery', authentication_classes=[]), name='identity-password-confirm'), path('api/v1/auth/password-change', PasswordChangeView.as_view(), name='identity-password-change')]
